import math

def is_perfect_cube(n):
    if n == 0:
        return 0
    # Calculate the cube root and check if it's an integer
    root = round(n**(1/3))
    return root**3 == n

# Target equation: a^3 = 8*b^3 - 65
# Search range: b from -15 to 15 (expanding beyond [-5, 5])

solutions = []
for b in range(-15, 16):
    n = 8 * (b**3) - 65
    if is_perfect_cube(n):
        a = round(n**(1/3))
        if a**3 == n:
            solutions.append((b, a))

print("Integer solutions (b, a) found for 8b^3 - a^3 = 65:")
if solutions:
    for b, a in solutions:
        print(f"b = {b}, a = {a}")
else:
    print("No integer solutions found in the search range.")

import math

def is_perfect_cube(n):
    if n == 0:
        return 0

    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Calculate the cube root of the absolute value
    # Use round() on the float result to get the nearest integer
    root_abs = round(n**(1/3))

    # Check if the cube of the rounded integer equals the absolute value
    if root_abs**3 == n:
        return sign * root_abs
    return None

# Target equation: a^3 = 8*b^3 - 65
